                        labelKey: 'r5_b_label',
                        options: [
                            { value: 0, labelKey: 'r5_b_opt0', cost: 0 },
                            { value: 1, labelKey: 'r5_b_opt1', cost: 300000 },
                            { value: 2, labelKey: 'r5_b_opt2', cost: 800000 }
                        ]
                    },
                    decisionC: {
                        labelKey: 'r5_c_label', desc: true,
                        options: [
                            { value: 0, labelKey: 'r5_c_opt0', cost: 0 },
                            { value: 1, labelKey: 'r5_c_opt1', cost: 400000 },
                            { value: 2, labelKey: 'r5_c_opt2', cost: 800000 }
                        ]
                    }
                }
            ];

            this.EVENTS = [
                [
                    { key: 'evt_r1_a', nps: -8, cost: 0 },
                    { key: 'evt_r1_b', nps: 0, cost: 1200000 },
                    { key: 'evt_r1_c', nps: -5, cost: 400000 },
                    { key: 'evt_r1_d', nps: 3, cost: 0 }
                ],
                [
                    { key: 'evt_r2_a', nps: -11, cost: 0, platformMitigated: true },
                    { key: 'evt_r2_b', nps: -3, cost: 800000 },
                    { key: 'evt_r2_c', nps: 0, cost: 0, revenueBoost: 500000 },
                    { key: 'evt_r2_d', nps: -2, cost: 1100000 }
                ],
                [
                    { key: 'evt_r3_a', nps: -6, cost: 0, ecomHit: 2 },
                    { key: 'evt_r3_b', nps: -4, cost: 0, fulfillMitigated: true },
                    { key: 'evt_r3_c', nps: -3, cost: 380000 },
                    { key: 'evt_r3_d', nps: 2, cost: 0, priceMitigated: true }
                ],
                [
                    { key: 'evt_r4_a', nps: 0, cost: 240000, cdpMitigated: true },
                    { key: 'evt_r4_b', nps: -5, cost: 180000 },
                    { key: 'evt_r4_c', nps: 4, cost: 0, loyaltyBoost: 5 },
