        initialize(state) {
            if (!state.domainState || Object.keys(state.domainState).length === 0) {
                state.domainState = {
                    budget: 18000000,
                    revenue: 380000000,
                    ecomPercent: 8.0,
                    ebitdaMargin: 9.4,
                    nps: 31,
                    costPerOrder: 14.20,
                    loyaltyPercent: 22,
                    gmroi: 1.80,
                    inventoryAccuracy: 71,
                    unifiedProfiles: 0,
                    platformLevel: 0,
                    inventoryLevel: 0,
                    orgLevel: 0,
                    bopisLevel: 0,
                    fulfillLevel: 0,
                    lastMileLevel: 0,
                    pricingLevel: 0,
                    assortLevel: 0,
                    parityLevel: 0,
                    cdpLevel: 0,
                    loyaltyLevel: 0,
                    personLevel: 0,
                    storeOptLevel: 0,
                    marketplaceLevel: 0,
                    socialLevel: 0,
                    totalInvested: 0,
                    revenueHistory: [],
                    ecomHistory: [],
                    ebitdaHistory: [],
                    npsHistory: [],
                    cpoHistory: [],
                    eventLog: []
                };
            }
            if (!state.decisions || Object.keys(state.decisions).length === 0) {
                state.decisions = {
                    decisionA: 0,
                    decisionB: 0,
                    decisionC: 0
                };
            }
            this._updateBriefing(state);
        }

        validateDecisions(decisions) {
            var selA = document.getElementById('decisionA');
            var selB = document.getElementById('decisionB');
            var selC = document.getElementById('decisionC');

            if (selA) decisions.decisionA = parseInt(selA.value);
            if (selB) decisions.decisionB = parseInt(selB.value);
            if (selC) decisions.decisionC = parseInt(selC.value);

            var st = window.mySimulation.state;
            var roundIdx = Math.min((st.currentPeriod || 1) - 1, this.ROUNDS.length - 1);
            var round = this.ROUNDS[roundIdx];

            var costA = optCost(round.decisionA, decisions.decisionA);
            var costB = optCost(round.decisionB, decisions.decisionB);
            var costC = optCost(round.decisionC, decisions.decisionC);
            var totalCost = costA + costB + costC;

            if (totalCost > st.domainState.budget) {
                window.mySimulation.uiManager.showNotification(
                    window.mySimulation.t('budget_exceeded'), 'warning'
                );
                return false;
            }

            this._updateBriefing(window.mySimulation.state);
            return true;
        }

        calculateResults(state) {
            var d = state.decisions;
            var ds = state.domainState;
            var roundIdx = Math.min((state.currentPeriod || 1) - 1, this.ROUNDS.length - 1);
            var round = this.ROUNDS[roundIdx];

            var costA = optCost(round.decisionA, d.decisionA);
            var costB = optCost(round.decisionB, d.decisionB);
            var costC = optCost(round.decisionC, d.decisionC);
            var roundCost = costA + costB + costC;

            ds.budget -= roundCost;
            ds.totalInvested += roundCost;

            var eventPool = this.EVENTS[roundIdx];
            var eventIdx = Math.floor(Math.random() * eventPool.length);
            var evt = eventPool[eventIdx];
            var eventNps = evt.nps;
            var eventCost = evt.cost;
            var eventRevBoost = evt.revenueBoost || 0;

            if (evt.platformMitigated && ds.platformLevel >= 2) {
                eventNps = Math.round(eventNps * 0.3);
                eventCost = Math.round(eventCost * 0.3);
            }
            if (evt.fulfillMitigated && ds.fulfillLevel >= 1) {
                eventNps = Math.round(eventNps * 0.4);
            }
            if (evt.cdpMitigated && ds.cdpLevel >= 2) {
                eventCost = Math.round(eventCost * 0.2);
            }
            if (evt.priceMitigated && ds.parityLevel >= 1) {
                eventNps = 0;
            }

            ds.budget -= eventCost;
            ds.eventLog.push(evt.key);

            if (roundIdx === 0) {
                ds.platformLevel = d.decisionA;
                ds.inventoryLevel = d.decisionB;
                ds.orgLevel = d.decisionC;

                var ecomGrowth = 0.5 + d.decisionA * 1.2 + d.decisionB * 0.8;
                ds.ecomPercent = Math.min(ds.ecomPercent + ecomGrowth, 50);
                ds.nps += (-2 + d.decisionC * 3) + eventNps;
                ds.inventoryAccuracy += d.decisionB * 8;
                ds.ebitdaMargin += -0.3 + d.decisionA * 0.1;
                ds.costPerOrder -= d.decisionB * 0.5;
                ds.revenue += eventRevBoost;
            }
            else if (roundIdx === 1) {
                ds.bopisLevel = d.decisionA;
                ds.fulfillLevel = d.decisionB;
                ds.lastMileLevel = d.decisionC;

                var invAccFactor = ds.inventoryAccuracy > 85 ? 1.0 : 0.5;
                var bopisImpact = d.decisionA * 1.5 * invAccFactor;
                ds.ecomPercent = Math.min(ds.ecomPercent + bopisImpact + d.decisionB * 0.8, 50);
                ds.costPerOrder -= (d.decisionA * 1.2 + d.decisionB * 1.5 + d.decisionC * 0.8) * invAccFactor;
                ds.nps += (d.decisionA * 2 + d.decisionB * 1 - 1) + eventNps;
                ds.revenue += (d.decisionA * 2000000 + d.decisionB * 1500000) * invAccFactor + eventRevBoost;
                ds.ebitdaMargin += d.decisionA * 0.2 + d.decisionB * 0.3 - 0.1;
                ds.gmroi += d.decisionB * 0.08;
            }
            else if (roundIdx === 2) {
                ds.pricingLevel = d.decisionA;
                ds.assortLevel = d.decisionB;
                ds.parityLevel = d.decisionC;

                var platformFactor = ds.platformLevel >= 2 ? 1.2 : 0.7;
                ds.ebitdaMargin += (d.decisionA * 1.2 + d.decisionB * 0.4) * platformFactor;
                ds.gmroi += (d.decisionA * 0.12 + d.decisionB * 0.1) * platformFactor;
                ds.nps += (d.decisionC * 3 - 1) + eventNps;
                ds.ecomPercent = Math.min(ds.ecomPercent + d.decisionB * 1.5 + d.decisionA * 0.5, 50);
                ds.revenue += (d.decisionA * 3000000 + d.decisionB * 2000000) * platformFactor + eventRevBoost;
                ds.costPerOrder -= d.decisionA * 0.4;
                if (evt.ecomHit) ds.ecomPercent = Math.max(ds.ecomPercent - evt.ecomHit, 5);
            }
            else if (roundIdx === 3) {
                ds.cdpLevel = d.decisionA;
                ds.loyaltyLevel = d.decisionB;
                ds.personLevel = d.decisionC;

                var dataFactor = ds.platformLevel >= 2 && ds.inventoryLevel >= 1 ? 1.3 : 0.6;
                ds.unifiedProfiles = Math.min(d.decisionA * 25, 95);
                ds.loyaltyPercent = Math.min(ds.loyaltyPercent + d.decisionB * 12 + d.decisionC * 5, 75);
                ds.nps += (d.decisionA * 2 + d.decisionB * 3 + d.decisionC * 2) * dataFactor * 0.5 + eventNps;
                ds.revenue += (d.decisionA * 2000000 + d.decisionB * 1500000 + d.decisionC * 3000000) * dataFactor + eventRevBoost;
                ds.ebitdaMargin += (d.decisionC * 0.8 + d.decisionB * 0.3) * dataFactor;
                ds.ecomPercent = Math.min(ds.ecomPercent + d.decisionC * 1.5, 50);
                if (evt.loyaltyBoost) ds.loyaltyPercent = Math.min(ds.loyaltyPercent + evt.loyaltyBoost, 75);
            }
            else if (roundIdx === 4) {
                ds.storeOptLevel = d.decisionA;
                ds.marketplaceLevel = d.decisionB;
                ds.socialLevel = d.decisionC;

                var omniMaturity = (ds.platformLevel + ds.cdpLevel + ds.bopisLevel + ds.fulfillLevel) / 12;
                if (d.decisionA === 1) {
                    ds.budget += 2000000;
                    ds.revenue -= 5000000;
                    ds.ebitdaMargin += 0.5;
                } else if (d.decisionA >= 2) {
                    ds.revenue += d.decisionA * 3000000 * omniMaturity;
                    ds.ebitdaMargin += d.decisionA * 0.4 * omniMaturity;
                }
                ds.ecomPercent = Math.min(ds.ecomPercent + d.decisionB * 2.5 + d.decisionC * 1.5, 50);
                ds.revenue += (d.decisionB * 4000000 + d.decisionC * 2500000) * omniMaturity + eventRevBoost;
                ds.nps += (d.decisionC * 2 + d.decisionB * 1) + eventNps;
                ds.ebitdaMargin += d.decisionB * 0.2 - (d.decisionB === 2 ? 0.3 : 0);
                if (evt.ecomHit) ds.ecomPercent = Math.max(ds.ecomPercent - evt.ecomHit, 5);
            }

            if (state.currentPeriod > 1) {
                ds.budget += 5000000;
            }
            if (ds.ebitdaMargin >= 9.0) {
                ds.budget += 1500000;
            }

            ds.nps = Math.max(0, Math.min(100, Math.round(ds.nps * 10) / 10));
            ds.costPerOrder = Math.max(3.0, Math.round(ds.costPerOrder * 100) / 100);
            ds.ebitdaMargin = Math.max(0, Math.round(ds.ebitdaMargin * 100) / 100);
            ds.ecomPercent = Math.max(0, Math.round(ds.ecomPercent * 10) / 10);
            ds.gmroi = Math.max(0.5, Math.round(ds.gmroi * 100) / 100);
            ds.inventoryAccuracy = Math.min(99, Math.round(ds.inventoryAccuracy));

            ds.revenueHistory.push(ds.revenue);
            ds.ecomHistory.push(ds.ecomPercent);
            ds.ebitdaHistory.push(ds.ebitdaMargin);
            ds.npsHistory.push(ds.nps);
            ds.cpoHistory.push(ds.costPerOrder);

            var eventEl = document.getElementById('eventPanel');
            var eventTextEl = document.getElementById('eventText');
            if (eventEl && eventTextEl) {
                eventEl.style.display = 'block';
                eventTextEl.innerHTML = window.mySimulation.t(evt.key);
            }

            var self = this;
            setTimeout(((__eqilNext) => function() {
                self._updateBriefing({ currentPeriod: __eqilNext });
            })(state.currentPeriod + 1), 500);

            // v1.1.0 fix: persist composite where Express reporting reads it.
            // results_utils.php express_resolveDomainScore(): performance.overallScore, then top-level score.
            var composite = this._score(ds);
            ds.score = composite;
            if (!ds.performance || typeof ds.performance !== 'object') ds.performance = {};
            ds.performance.overallScore = composite;
            return {
                period: state.currentPeriod,
                roundCost: roundCost,
                eventKey: evt.key,
                revenue: ds.revenue,
                ecomPercent: ds.ecomPercent,
                ebitdaMargin: ds.ebitdaMargin,
                nps: ds.nps,
                costPerOrder: ds.costPerOrder,
                budget: ds.budget,
                gmroi: ds.gmroi
            };
        }

