        _score(ds) {
            var nps = ds.nps || 31, ecom = ds.ecomPercent || 8, ebitda = ds.ebitdaMargin || 9.4,
                cpo = ds.costPerOrder || 14.20, loyalty = ds.loyaltyPercent || 22;
            var score = 0;
            if (nps >= 55) score += 25; else if (nps >= 42) score += 18; else if (nps >= 35) score += 10;
            if (cpo <= 7.50) score += 25; else if (cpo <= 10.50) score += 18; else if (cpo <= 12.00) score += 10;
            if (ecom >= 28) score += 20; else if (ecom >= 18) score += 14; else if (ecom >= 12) score += 7;
            if (ebitda >= 12) score += 15; else if (ebitda >= 10) score += 10; else if (ebitda >= 9) score += 5;
            if (loyalty >= 55) score += 15; else if (loyalty >= 40) score += 10; else if (loyalty >= 30) score += 5;
            return score;
        }

        getPerformanceSummary(history) {
            if (!history.length) return {};
            var t = function(k){ return window.mySimulation.t(k); };
            var last = history[history.length - 1];
            var ds = last.domainState || {};
            var finalNps = ds.nps || 31;
            var finalEcom = ds.ecomPercent || 8;
            var finalEbitda = ds.ebitdaMargin || 9.4;
            var finalCpo = ds.costPerOrder || 14.20;
            var finalGmroi = ds.gmroi || 1.80;
            var finalLoyalty = ds.loyaltyPercent || 22;

            var score = this._score(ds);
            var performanceId = 'stage2', gradeKey = 'grade_stage2';
            var insights = [];
            if (score >= 80) { performanceId = 'stage5'; gradeKey = 'grade_stage5'; insights.push(t('insight_excellent')); }
            else if (score >= 60) { performanceId = 'stage4'; gradeKey = 'grade_stage4'; insights.push(t('insight_good')); }
            else if (score >= 40) { performanceId = 'stage3'; gradeKey = 'grade_stage3'; insights.push(t('insight_average')); }
            else { insights.push(t('insight_weak')); }

            if (finalCpo > 10) insights.push(t('insight_cpo'));
            if (finalNps < 40) insights.push(t('insight_nps'));
            if (finalEcom < 15) insights.push(t('insight_ecom'));
            if (finalLoyalty < 35) insights.push(t('insight_loyalty'));

            return {
                score: score,
                overallScore: score,
                performance: t(gradeKey),
                performanceId: performanceId,
                beatTarget: score >= 60,
                finalNps: finalNps,
                finalEcom: finalEcom,
                finalEbitda: finalEbitda,
                finalCpo: finalCpo,
                finalGmroi: finalGmroi,
                finalLoyalty: finalLoyalty,
                totalInvested: ds.totalInvested || 0,
                insights: insights
            };
        }

